111	 * Logs a session out. The row is removed by expiring it: `SessionPrincipal`
112	 * exposes no session id, so the sweep is what actually clears the row, and the
113	 * cookie is dropped by the caller either way.
114	 */
115	export async function destroySession(token: string): Promise<void> {
116	  const principal = await resolveSession(token);
117	  if (!principal) return;
118	
119	  await sessionRepo.purgeExpiredSessions(toIsoTimestamp(new Date()));
120	}
