/** Cascade behind removing a member: their open work no longer has an owner. */
export async function unassignAllForUser(
  orgId: OrgId,
  userId: UserId,
): Promise<number> {
  const rows = getDb()
    .update(issues)
    .set({ assigneeId: null, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.assigneeId, userId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .returning({ id: issues.id })
    .all();

  return rows.length;
}

/** Live, still-open issues whose due date has passed. Drives the overdue job. */

