/**
 * Accepting runs unauthenticated: the token is the credential, so there is no
 * `Actor` to scope against and every check has to come off the stored row.
 *
 * Three shapes of "who is accepting": nobody has ever been a member (insert a
 * row), a current member is re-accepting (the invitation is consumed but
 * nothing about them changes), or a former member is coming back (their old
 * row is restored rather than replaced, so whatever it pointed at is still
 * attached). Either way the invitation itself is used up by this acceptance
 * and can never be replayed.
 */
export async function acceptInvitation(
  userId: UserId,
  input: AcceptInvitationTokenInput,
): Promise<Member> {
  const invitation = requireFound(
    await invitationRepo.findInvitationByTokenHash(hashToken(input.token)),
    "Invitation",
    "token",
  );

  if (invitation.revokedAt !== null) {
    throw new Error("That invitation has been revoked");
  }
  if (invitation.acceptedAt !== null) {
    throw new Error("That invitation has already been accepted");
  }
  if (invitation.expiresAt <= toIsoTimestamp(new Date())) {
    throw new Error("That invitation has expired");
  }

  const existing = await memberRepo.findMemberIncludingArchived(
    invitation.orgId,
    userId,
  );
  const now = toIsoTimestamp(new Date());

  let member: Member;
  let rejoined = false;

  if (existing === null) {
    member = await memberRepo.insertMember(
      invitation.orgId,
      userId,
      invitation.role,
      invitation.invitedBy,
    );
    rejoined = true;
  } else if (existing.archivedAt !== null) {
    member = await memberRepo.restoreMember(invitation.orgId, existing.id, {
      role: invitation.role,
      invitedBy: invitation.invitedBy,
      joinedAt: now,
    });
    rejoined = true;
  } else {
    member = existing;
  }

  await invitationRepo.markInvitationAccepted(invitation.orgId, invitation.id, now);

  if (rejoined) {
    await emit("member.joined", {
      ...envelope(invitation.orgId, userId),
      memberId: member.id,
      userId,
      role: member.role,
    });
  }

  return member;
}

