import { afterAll, beforeAll, describe, expect, it } from "vitest";

import * as memberRepo from "@/server/repositories/member-repository";
import * as memberService from "@/server/services/member-service";
import * as sessionService from "@/server/services/session-service";
import * as invitationService from "@/server/services/invitation-service";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as issueService from "@/server/services/issue-service";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectService from "@/server/services/project-service";
import * as notificationService from "@/server/services/notification-service";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import { randomToken, hashToken } from "@/lib/hash";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("scratch verification", () => {
  it("removed member cannot resolve as actor or switch into the org", async () => {
    const tenant = await createTenant("scratch-security", "growth");
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!target) throw new Error("missing");

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: target.id,
    });

    const actor = await memberService.resolveActor(tenant.userIds.viewer, tenant.org.id);
    expect(actor).toBeNull();

    const principal = {
      userId: tenant.userIds.viewer,
      email: "x@x.test",
      activeOrgId: tenant.org.id,
      expiresAt: "2999-01-01T00:00:00.000Z" as never,
    };

    await expect(
      sessionService.switchActiveOrg(principal, { orgId: tenant.org.id }),
    ).rejects.toThrow(/not a member/);
  });

  it("removing an archived member again, or changing their role, is a conflict and frees no seat", async () => {
    const tenant = await createTenant("scratch-conflict", "growth");
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!target) throw new Error("missing");

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: target.id,
    });

    await expect(
      memberService.removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: target.id,
      }),
    ).rejects.toMatchObject({ code: "conflict" });

    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: target.id,
        role: "admin",
      }),
    ).rejects.toMatchObject({ code: "conflict" });
  });

  it("removal unassigns their issues and clears project lead", async () => {
    const tenant = await createTenant("scratch-cascade", "growth");
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    if (!target) throw new Error("missing");

    const issue = await issueService.createIssue(tenant.actors.owner, {
      ...issueInput(tenant.org.id, tenant.project.id),
      assigneeId: tenant.userIds.member,
    } as never);

    const led = await projectService.createProject(tenant.actors.owner, {
      orgId: tenant.org.id,
      name: "Led project",
      slug: "led-project",
      key: "LED",
      description: null,
      visibility: "org",
      leadId: tenant.userIds.member,
      color: "#6366f1",
      targetDate: null,
    });

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: target.id,
    });

    const afterIssue = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(afterIssue?.assigneeId).toBeNull();

    const afterProject = await memberService.listMembers(tenant.actors.owner, {
      orgId: tenant.org.id,
      limit: 10,
      cursor: null,
    });
    void afterProject;

    const { getDb, projects } = await import("@/server/db");
    const { eq } = await import("drizzle-orm");
    const row = getDb().select().from(projects).where(eq(projects.id, led.id)).get();
    expect(row?.leadId).toBeNull();
  });

  it("cannot assign an issue or a project lead to a non-member", async () => {
    const tenant = await createTenant("scratch-assign", "growth");
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    if (!target) throw new Error("missing");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: target.id,
    });

    await expect(
      issueService.createIssue(tenant.actors.owner, {
        ...issueInput(tenant.org.id, tenant.project.id),
        assigneeId: tenant.userIds.member,
      } as never),
    ).rejects.toThrow(/not a current member/);

    await expect(
      projectService.createProject(tenant.actors.owner, {
        orgId: tenant.org.id,
        name: "Bad lead",
        slug: "bad-lead",
        key: "BAD",
        description: null,
        visibility: "org",
        leadId: tenant.userIds.member,
        color: "#6366f1",
        targetDate: null,
      }),
    ).rejects.toThrow(/not a current member/);
  });

  it("accepting an invitation re-admits a former member on the same row, and consumes the invitation", async () => {
    const tenant = await createTenant("scratch-reinvite", "growth");
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!target) throw new Error("missing");

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: target.id,
    });

    const token = randomToken(32);
    const invitation = await invitationRepo.insertInvitation(
      tenant.org.id,
      { orgId: tenant.org.id, email: "viewer@scratch-reinvite.test", role: "admin", expiresInDays: 14 },
      tenant.userIds.owner,
      hashToken(token),
    );

    const member = await invitationService.acceptInvitation(tenant.userIds.viewer, { token });
    expect(member.id).toBe(target.id);
    expect(member.role).toBe("admin");
    expect(member.invitedBy).toBe(tenant.userIds.owner);
    expect(member.archivedAt).toBeNull();

    const actor = await memberService.resolveActor(tenant.userIds.viewer, tenant.org.id);
    expect(actor).not.toBeNull();

    const reused = await invitationRepo.findInvitationByTokenHash(hashToken(token));
    expect(reused?.acceptedAt).not.toBeNull();
    await expect(
      invitationService.acceptInvitation(tenant.userIds.viewer, { token }),
    ).rejects.toThrow(/already been accepted/);
    void invitation;
  });

  it("a current member accepting an invitation is unchanged but consumes it", async () => {
    const tenant = await createTenant("scratch-noop-accept", "growth");
    const token = randomToken(32);
    await invitationRepo.insertInvitation(
      tenant.org.id,
      { orgId: tenant.org.id, email: "member@scratch-noop-accept.test", role: "admin", expiresInDays: 14 },
      tenant.userIds.owner,
      hashToken(token),
    );

    const before = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    const member = await invitationService.acceptInvitation(tenant.userIds.member, { token });
    expect(member.role).toBe(before?.role);

    const reused = await invitationRepo.findInvitationByTokenHash(hashToken(token));
    expect(reused?.acceptedAt).not.toBeNull();
  });

  it("notify() and the digest skip a former member", async () => {
    const tenant = await createTenant("scratch-notify", "growth");
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!target) throw new Error("missing");

    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.viewer,
      kind: "issue_overdue",
      inApp: true,
      email: true,
      digestOnly: true,
    });

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: target.id,
    });

    const notifications = await notificationService.notify(
      tenant.org.id,
      "issue_overdue",
      [tenant.userIds.viewer],
      { title: "t", body: "b", href: "/x", actorId: null },
    );
    expect(notifications).toHaveLength(0);

    const subscribers = await preferenceRepo.listDigestSubscribers(tenant.org.id);
    expect(subscribers).not.toContain(tenant.userIds.viewer);
  });
});

