    const reused = await invitationRepo.findInvitationByTokenHash(hashToken(token));
    expect(reused?.acceptedAt).not.toBeNull();
    await expect(
      invitationService.acceptInvitation(tenant.userIds.viewer, { token }),
    ).rejects.toThrow(/already been accepted/);
    void invitation;
  });

  it("a current member accepting an invitation is unchanged but consumes it", async () => {
    const tenant = await createTenant("scratch-noop-accept", "growth");
    const token = randomToken(32);
    await invitationRepo.insertInvitation(
      tenant.org.id,
      { orgId: tenant.org.id, email: "member@scratch-noop-accept.test", role: "admin", expiresInDays: 14 },
      tenant.userIds.owner,
      hashToken(token),
    );

    const before = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    const member = await invitationService.acceptInvitation(tenant.userIds.member, { token });
    expect(member.role).toBe(before?.role);

    const reused = await invitationRepo.findInvitationByTokenHash(hashToken(token));
    expect(reused?.acceptedAt).not.toBeNull();
  });

  it("notify() and the digest skip a former member", async () => {
    const tenant = await createTenant("scratch-notify", "growth");
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!target) throw new Error("missing");

    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.viewer,
      kind: "issue_overdue",
      inApp: true,
      email: true,
      digestOnly: true,
    });

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: target.id,
    });

    const notifications = await notificationService.notify(
      tenant.org.id,
      "issue_overdue",
      [tenant.userIds.viewer],
      { title: "t", body: "b", href: "/x", actorId: null },
    );
    expect(notifications).toHaveLength(0);

    const subscribers = await preferenceRepo.listDigestSubscribers(tenant.org.id);
    expect(subscribers).not.toContain(tenant.userIds.viewer);
  });
});
